    super.initState();
    _dashboardFuture = _loadDashboard();
  }

  Future<DashboardData> _loadDashboard() async {
    final CurrencyRepository currencyRepository = context.read<CurrencyRepository>();
    final NewsRepository newsRepository = context.read<NewsRepository>();

    // Свежий курс валют и свежая лента новостей запрашиваются параллельно.
    final List<Object> results = await Future.wait<Object>([
      currencyRepository.fetchRates(const CurrencyPageRequest()),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]);

    final CurrencyPage currencyPage = results[0] as CurrencyPage;
    final List<NewsModel> news = results[1] as List<NewsModel>;

    return DashboardData(
      rates: currencyPage.items.take(_ratesPreviewLimit).toList(growable: false),
      news: news.take(_newsPreviewLimit).toList(growable: false),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.dashboard)),
      body: FutureBuilder<DashboardData>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<DashboardData> snapshot) {
          final DashboardData? data = snapshot.data;
          if (data == null) return const Center(child: CircularProgressIndicator());

          return ListView(
            padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
            children: [
              DashboardSection(
                title: context.loc.currencyRate,
                child: Column(
                  children: [
                    for (final CurrencyModel currency in data.rates)
                      Padding(
                        key: ValueKey(currency.id),
                        padding: const EdgeInsets.only(bottom: 10),
                        child: CurrencyCard(model: currency),
                      ),
                  ],
                ),
              ),
              Padding(
                padding: const EdgeInsets.only(top: 16),
                child: DashboardSection(
                  title: context.loc.news,
                  child: Column(
                    children: [
                      for (final NewsModel news in data.news)
                        Padding(
                          key: ValueKey(news.link),
                          padding: const EdgeInsets.only(bottom: 16),
                          child: NewsCard(model: news),
                        ),
                    ],
                  ),
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

